<?php $success=sessionSuccess();$error=sessionError(); ?><!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Students - DormSync</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#f7f9fc;color:#172033;margin:0}.topbar{background:#fff;border-bottom:1px solid #e7ebf2;padding:18px 6%}.topbar a{color:#2563eb;text-decoration:none}main{max-width:1150px;margin:auto;padding:36px 24px}.panel{background:#fff;border:1px solid #e7ebf2;border-radius:8px;padding:22px}.toolbar{display:flex;gap:8px;margin:18px 0}.toolbar input{flex:1;padding:10px;border:1px solid #cbd5e1;border-radius:6px}.button{background:#2563eb;color:#fff;border-radius:6px;padding:10px 14px;text-decoration:none;border:0}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:760px}th,td{border-bottom:1px solid #e7ebf2;padding:12px 10px;text-align:left;font-size:13px}th{color:#718096;font-size:11px;text-transform:uppercase}.action{color:#2563eb;text-decoration:none}.message{padding:10px;margin-bottom:12px;background:#dcfce7;color:#166534}.error{background:#fee2e2;color:#991b1b}</style></head><body><header class="topbar"><a href="/warden/dashboard">Back to dashboard</a></header><main><h1>Assigned hostel students</h1><?php if($success):?><div class="message"><?=htmlspecialchars($success)?></div><?php endif;?><?php if($error):?><div class="message error"><?=htmlspecialchars($error)?></div><?php endif;?><div class="toolbar"><form method="get" style="display:flex;gap:8px;flex:1"><input name="search" value="<?=htmlspecialchars($search)?>" placeholder="Search name, ID, or email"><button class="button" type="submit">Search</button></form><a class="button" href="/warden/student-create">Add student</a></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Student ID</th><th>Email</th><th>Room</th><th>Block</th><th>Phone</th><th>Action</th></tr></thead><tbody><?php if($rows):foreach($rows as $row):?><tr><td><?=htmlspecialchars($row['full_name'])?></td><td><?=htmlspecialchars($row['student_id'])?></td><td><?=htmlspecialchars($row['email'])?></td><td><?=htmlspecialchars($row['room_number']??'Not assigned')?></td><td><?=htmlspecialchars($row['block']??'-')?></td><td><?=htmlspecialchars($row['phone']??'-')?></td><td><a class="action" href="/warden/student-view/<?= (int)$row['id'] ?>">View/Edit</a></td></tr><?php endforeach;else:?><tr><td colspan="7">No students found.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
